import{_ as i,o as h,c as t,a2 as a}from"./chunks/framework.62rcL0wY.js";const o=JSON.parse('{"title":"Clickermann v4.13 Tiếng Việt","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),c={name:"index.md"};function l(e,n,r,g,s,u){return h(),t("div",null,[...n[0]||(n[0]=[a(`<h1 id="clickermann-v4-13-tieng-viet" tabindex="-1">Clickermann v4.13 Tiếng Việt <a class="header-anchor" href="#clickermann-v4-13-tieng-viet" aria-label="Permalink to &quot;Clickermann v4.13 Tiếng Việt&quot;">​</a></h1><p>Trang này giới thiệu tổng quan về Clickermann v4.13 chạy trên hệ điều hành <strong>Windows</strong>, cách chương trình hoạt động và danh mục toàn bộ các trang hướng dẫn trong bộ tài liệu. Đây là tài liệu cộng đồng dành cho người Việt mới học, không phải tài liệu chính thức của tác giả.</p><div class="tip custom-block"><p class="custom-block-title">Lộ trình cho người mới</p><p>Mới bắt đầu? Đọc lần lượt <a href="/clickermann-guide-vi/bat-dau/cai-dat.html">Cài đặt</a> → <a href="/clickermann-guide-vi/bat-dau/man-hinh-chinh.html">Màn hình chính</a> → <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a> → <a href="/clickermann-guide-vi/bat-dau/script-dau-tien.html">Viết script đầu tiên</a>, rồi chọn một trang trong mục Cẩm nang.</p></div><div class="warning custom-block"><p class="custom-block-title">Lưu ý kiểm chứng thực tế</p><p>Toàn bộ tài liệu chưa chạy thử trên Windows; nếu màn hình của bạn khác, hãy tin màn hình.</p></div><h2 id="clickermann-la-gi" tabindex="-1">Clickermann là gì? <a class="header-anchor" href="#clickermann-la-gi" aria-label="Permalink to &quot;Clickermann là gì?&quot;">​</a></h2><p>Clickermann là chương trình chạy trên <strong>Windows</strong>, giúp mô phỏng thao tác chuột và bàn phím của người dùng trên máy tính, đồng thời hỗ trợ nhiều tính năng xử lý khác. Chương trình hoạt động dựa trên các <strong>script</strong> (còn gọi là kịch bản hay macro) do người dùng tự gõ vào hoặc ghi lại trực tiếp trong lúc thao tác. Các script hoàn toàn mở để chỉnh sửa bằng bất kỳ trình soạn thảo văn bản nào, hoặc bằng chính trình soạn thảo được tối ưu riêng đi kèm trong Clickermann.</p><p>Chương trình được tạo ra để tự động hóa các thao tác lặp đi lặp lại đơn giản trên máy tính. Trong thực tế, chương trình có thể dùng cho nhiều công việc khác nhau, chẳng hạn như tự động sao chép dữ liệu từ các phần mềm chưa hỗ trợ sẵn tính năng xuất dữ liệu.</p><p>Trang chủ chính thức của tác giả J.Challenger: <a href="http://crapware.aidf.org" target="_blank" rel="noreferrer">http://crapware.aidf.org</a> (tài liệu này không đính kèm tệp <code>.exe</code>).</p><h2 id="cach-lam-viec-voi-chuong-trinh" tabindex="-1">Cách làm việc với chương trình <a class="header-anchor" href="#cach-lam-viec-voi-chuong-trinh" aria-label="Permalink to &quot;Cách làm việc với chương trình&quot;">​</a></h2><p>Chương trình thực hiện các thao tác dựa trên tập hợp lệnh trong script. Có hai cách để tạo một script:</p><ol><li><strong>Tự viết script bằng tay:</strong> Dựa vào tài liệu hướng dẫn và trình soạn thảo tích hợp. Cách này giúp tạo ra các script linh hoạt, tự kiểm tra điều kiện để xử lý từng tình huống, nhưng đòi hỏi người dùng nắm kiến thức cơ bản và tư duy logic.</li><li><strong>Dùng hệ thống ghi thao tác (Record):</strong> Để chương trình tự viết script bằng cách ghi lại các hành động bạn vừa làm. Cách này giúp người dùng không phải gõ lệnh thủ công, nhưng kém linh hoạt hơn vì chỉ lặp lại đúng các thao tác đã ghi.</li></ol><p>Tác giả khuyến nghị bạn nên tìm hiểu cách tự viết script bằng tay vì đây là chế độ làm việc chính của chương trình, còn chức năng ghi tự động là phần bổ trợ thêm.</p><h2 id="ngon-ngu-script" tabindex="-1">Ngôn ngữ script <a class="header-anchor" href="#ngon-ngu-script" aria-label="Permalink to &quot;Ngôn ngữ script&quot;">​</a></h2><p>Ngôn ngữ script của Clickermann được thiết kế đơn giản, chạy lần lượt từng dòng lệnh từ trên xuống dưới nên người mới chưa từng lập trình vẫn có thể làm quen nhanh chóng.</p><p>Dưới đây là ví dụ một script đơn giản bấm chuột trái một lần vào tọa độ <code>(100, 200)</code>, chờ 1 giây rồi dừng hẳn; nếu bỏ dòng <code>HALT</code> ở cuối thì sau khi chạy xong dòng cuối, script sẽ tự động quay lại dòng đầu tiên và lặp lại:</p><div class="language-cms vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cms</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Bấm chuột trái tại tọa độ X = 100, Y = 200</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LCLICK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Chờ 1 giây</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WAIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Dừng hẳn script (nếu bỏ dòng này thì script sẽ tự lặp lại từ đầu)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HALT</span></span></code></pre></div><h2 id="quy-uoc-nhan-kiem-chung" tabindex="-1">Quy ước nhãn kiểm chứng <a class="header-anchor" href="#quy-uoc-nhan-kiem-chung" aria-label="Permalink to &quot;Quy ước nhãn kiểm chứng&quot;">​</a></h2><p>Mỗi lệnh và mục có điểm cần lưu ý trong tài liệu này được gắn nhãn hoặc tiền tố để bạn biết rõ nguồn gốc thông tin:</p><ul><li><code>🟡 Theo help, chưa chạy thử</code> — Nội dung dịch và biên soạn sát theo tài liệu <code>help.chm</code> chính thức (v4.13.014), chưa chạy kiểm chứng thực tế trên máy Windows.</li><li><code>🟠 Chưa thống nhất</code> — Có điểm mâu thuẫn giữa các phần trong help, giữa help với tài liệu cộng đồng (sách của Chô tô), hoặc help không nêu rõ. Mỗi mục đều có dòng gợi ý <strong>&quot;Nên làm&quot;</strong> ngay đầu, phần so sánh chi tiết nằm trong khung thu gọn và có hướng dẫn kiểm tra tại trang <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html">Cần kiểm tra trên Windows</a>.</li><li><strong>Suy luận:</strong> — Nhận định suy ra từ ví dụ hoặc thông tin gián tiếp trong help khi lời giải thích của help không ghi thẳng.</li><li><strong>Tham khảo:</strong> — Ý bổ sung từ tài liệu cộng đồng tiếng Việt (sách của Chô tô) tại những chỗ help chính thức không nói rõ.</li></ul><h2 id="danh-muc-toan-bo-tai-lieu" tabindex="-1">Danh mục toàn bộ tài liệu <a class="header-anchor" href="#danh-muc-toan-bo-tai-lieu" aria-label="Permalink to &quot;Danh mục toàn bộ tài liệu&quot;">​</a></h2><ul><li><strong>Bắt đầu:</strong><ul><li><a href="/clickermann-guide-vi/bat-dau/cai-dat.html">Cài đặt và chạy lần đầu</a></li><li><a href="/clickermann-guide-vi/bat-dau/man-hinh-chinh.html">Màn hình chính</a></li><li><a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo và kính lúp</a></li><li><a href="/clickermann-guide-vi/bat-dau/script-dau-tien.html">Viết script đầu tiên</a></li></ul></li><li><strong>Khái niệm cơ bản:</strong><ul><li><a href="/clickermann-guide-vi/khai-niem/ngon-ngu.html">Ngôn ngữ script</a></li><li><a href="/clickermann-guide-vi/khai-niem/bo-dem-anh.html">Bộ đệm ảnh</a></li><li><a href="/clickermann-guide-vi/khai-niem/toa-do.html">Hệ tọa độ màn hình và phần tử</a></li><li><a href="/clickermann-guide-vi/khai-niem/mau-sac.html">Màu sắc và giảm màu (<code>COLORMODE</code>)</a></li><li><a href="/clickermann-guide-vi/khai-niem/khoa-cua-so.html">Chế độ khóa cửa sổ</a></li></ul></li><li><strong>Cẩm nang:</strong><ul><li><a href="/clickermann-guide-vi/cam-nang/click-theo-lich.html">Bấm chuột theo lịch và chu kỳ</a></li><li><a href="/clickermann-guide-vi/cam-nang/tim-mau.html">Tìm màu trên màn hình rồi bấm chuột</a></li><li><a href="/clickermann-guide-vi/cam-nang/tim-anh.html">Tìm hình ảnh mẫu trên màn hình</a></li><li><a href="/clickermann-guide-vi/cam-nang/doc-ghi-file.html">Đọc và ghi tệp <code>.txt</code> và <code>.ini</code></a></li><li><a href="/clickermann-guide-vi/cam-nang/tu-ve.html">Tự động vẽ hình trong Paint</a></li><li><a href="/clickermann-guide-vi/cam-nang/thuc-chien.html">Thực chiến: kỹ thuật viết script</a></li></ul></li><li><strong>Xử lý lỗi:</strong><ul><li><a href="/clickermann-guide-vi/xu-ly-loi.html">Xử lý lỗi và câu hỏi thường gặp (FAQ)</a></li></ul></li><li><strong>Tra cứu lệnh:</strong><ul><li><a href="/clickermann-guide-vi/lenh/">Tổng quan tra cứu lệnh theo việc cần làm</a></li><li><a href="/clickermann-guide-vi/lenh/so.html">Số, biến và mảng</a></li><li><a href="/clickermann-guide-vi/lenh/chuoi-file.html">Chuỗi, tệp tin, bộ nhớ tạm và HTTP</a></li><li><a href="/clickermann-guide-vi/lenh/chuot.html">Chuột</a></li><li><a href="/clickermann-guide-vi/lenh/ban-phim.html">Bàn phím</a></li><li><a href="/clickermann-guide-vi/lenh/cau-truc.html">Điều kiện, vòng lặp, chương trình con</a></li><li><a href="/clickermann-guide-vi/lenh/man-hinh.html">Màn hình và màu sắc</a></li><li><a href="/clickermann-guide-vi/lenh/nhat-ky.html">Nhật ký và âm báo</a></li><li><a href="/clickermann-guide-vi/lenh/kich-ban.html">Điều khiển script và hệ thống</a></li><li><a href="/clickermann-guide-vi/lenh/winapi.html">Cửa sổ và WinAPI</a></li></ul></li><li><strong>Nâng cao:</strong><ul><li><a href="/clickermann-guide-vi/bat-dau/quan-ly-cua-so.html">Quản lý cửa sổ</a></li><li><a href="/clickermann-guide-vi/khai-niem/luong.html">Luồng (<code>THREAD</code>)</a></li><li><a href="/clickermann-guide-vi/khai-niem/plugin.html">Plugin mở rộng (DLL)</a></li><li><a href="/clickermann-guide-vi/nang-cao/alt-winmode.html">Thư viện alt_winmode</a></li></ul></li><li><strong>Phụ lục:</strong><ul><li><a href="/clickermann-guide-vi/phu-luc/ma-phim.html">Bảng mã phím và hằng số</a></li><li><a href="/clickermann-guide-vi/phu-luc/lich-su.html">Lịch sử phát triển phiên bản</a></li><li><a href="/clickermann-guide-vi/phu-luc/thuat-ngu.html">Bảng thuật ngữ đối chiếu</a></li><li><a href="/clickermann-guide-vi/phu-luc/lenh-an.html">Lệnh ẩn và lệnh không có tài liệu</a></li><li><a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html">Cần kiểm tra trên Windows</a></li><li><a href="/clickermann-guide-vi/phu-luc/nguon.html">Nguồn tài liệu và ghi công</a></li></ul></li></ul>`,21)])])}const d=i(c,[["render",l]]);export{o as __pageData,d as default};
